#include<bits/stdc++.h>

using namespace std;

const int INF = 1e9;

void upd(int& x, int y)
{
    if(x > y) x = y;
}

void solve()
{
    int n, k;
    cin >> n >> k;
    vector<int> p(n);
    for(int i = 0; i < n; i++)
    {
        cin >> p[i];
        p[i]--;
    }

    vector<bool> used(n);
    vector<int> len;
    for(int i = 0; i < n; i++)
    {
        if(!used[i])
        {
            used[i] = true;
            int cur_len = 1;
            int j = p[i];
            while(!used[j])
            {
                used[j] = true;
                cur_len++;
                j = p[j];
            }
            len.push_back(cur_len);
        }
    }
    sort(len.begin(), len.end());
    reverse(len.begin(), len.end());

    if(k == 1)
    {
        if(len[0] >= 3)
            cout << "Bob\n";
        else if(len[0] == 1 || n % 2 == 1)
            cout << "Alice\n";
        else 
            cout << "Bob\n";        
    }
    else if(len[0] > k + 1)
    {
        cout << "Bob\n";
    }
    else if(len[0] == k + 1)
    {
        if(len.size() > 1 && len[1] == k + 1)
        {
            cout << "Bob\n";
        }
        else
        {
            int must_remove = 0;
            int cnt1 = 0;
            for(int i = 1; i < len.size(); i++)
            {
                if(len[i] > 1)
                    must_remove += len[i];
                else cnt1++;
            }
            int alice_move = must_remove + cnt1 % (k + 1);
            if(alice_move > k || alice_move == 0)
                cout << "Bob\n";
            else
                cout << "Alice\n";
        }
    }
    else
    {                        
        int m = len.size();
        m = min(m, 2 * k);
        vector<vector<vector<int>>> dp(m+1, vector<vector<int>>(k+1, vector<int>(k + 1, INF)));
        dp[0][0][0] = 0;
        for(int i = 0; i < m; i++)
            for(int j = 0; j <= k; j++)
                for(int c = 0; c <= k; c++)
                {
                    if(dp[i][j][c] == INF) continue;
                    bool alice_can = (j + len[i] <= k);
                    bool bob_can = (i - c < k);
                    if(alice_can)
                        upd(dp[i+1][j + len[i]][c + 1], dp[i][j][c]);
                    upd(dp[i+1][j][c], dp[i][j][c] + (bob_can ? len[i] - 1 : 0));
                }
        bool alice_win = false;
        for(int j = 0; j <= k; j++)
            for(int c = 0; c <= k; c++)
                if(dp[m][j][c] <= k)
                    alice_win = true;

        if(alice_win)
            cout << "Alice\n";
        else
            cout << "Bob\n";
    }
}

