    for(int i = 0; i < t; i++)
        solve();
}

#include<bits/stdc++.h>

using namespace std;

const int MOD = 998244353;
const int N = 5005;

int add(int x, int y)
{
    x += y;
    while(x >= MOD) x -= MOD;
    while(x < 0) x += MOD;
    return x;
}

int mul(int x, int y)
{
    return (x * 1ll * y) % MOD;
}

int sub(int x, int y)
{
    return add(x, -y);
}

int binpow(int x, int y)
{
    int z = 1;
    while(y)
    {
        if(y & 1) z = mul(z, x);
        x = mul(x, x);
        y >>= 1;
    }
    return z;
}

int fact[N];
int inv[N];

void precalc()
{
    fact[0] = 1;
    for(int i = 1; i < N; i++)
        fact[i] = mul(i, fact[i - 1]);    
    for(int i = 0; i < N; i++)
        inv[i] = binpow(i, MOD - 2);
}

struct Blocks
{
    int n;
    vector<int> cutoff_pos;
    vector<int> pref;
    vector<int> pref_G;
    vector<pair<int, int>> a;

    void rebuild()
    {
        pref = { 0 };
        pref_G = { 0 };
        vector<bool> used(n);
        vector<pair<int, int>> b;
        cutoff_pos = vector<int>(n, -1);
        int sign = 1;
        int cnt = n - 1;
        for(int i = 0; i < a.size(); i++)
        {
            int x = a[i].first;
            int len = a[i].second;
            if(used[x])
                break;
            used[x] = true;
            b.push_back(make_pair(x, len));
            cutoff_pos[x] = i;
            int c = mul(sign, mul(len, fact[cnt]));
            int c_G = mul(sign, mul(len, fact[cnt - 1]));
            --cnt;
            sign = sub(0, sign);
            pref.push_back(add(pref.back(), c));
            pref_G.push_back(add(pref_G.back(), c_G));
        }

        a = b;
    }

    int getF()
    {
        return pref.back();
    }

    int getG(int x)
    {
        if(cutoff_pos[x] == -1) return pref_G.back();
        else return pref_G[cutoff_pos[x]];
    }

    void append(int x)
    {
        if(a.empty() || a[0].first != x)
            a.insert(a.begin(), make_pair(x, 0));
        a[0].second++;
        rebuild();
    }

    Blocks(int n = 0) : n(n) {};
};

void solve()
{
    int n;
    cin >> n;
    vector<int> a(n - 1);
    for(int i = 0; i < n - 1; i++)
    {
        cin >> a[i];
        a[i]--;
    }
    Blocks b(n);
    vector<vector<int>> ans(n - 1, vector<int>(n));
    vector<vector<int>> G(n - 1, vector<int>(n));
    vector<int> F(n - 1);
    for(int i = 0; i < n - 1; i++)
    {
        int x = a[i];
        b.append(x);
        F[i] = b.getF();
        for(int j = 0; j < n; j++)
            G[i][j] = b.getG(j);
        for(int j = 0; j < n; j++)
        {
            if(a[i] == j) continue;
            int s = add(fact[n - 1], G[i][j]);
            if(i > 0)
            {
                s = sub(s, G[i - 1][j]);
                if(a[i - 1] == j)
                    s = add(s, F[i - 1]);
            }
            ans[i][j] = s;   
        }
    }

    long long res = 0;
    for(int i = 0; i < n - 1; i++)
        for(int j = 0; j < n; j++)
            res ^= ans[i][j] * 1ll * (i + 1) * 1ll * (j + 1);
    cout << res << endl;
}

int main() 
{
    precalc();
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int t;
    cin >> t;
    for(int i = 0; i < t; i++)
        solve();   
}
